// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OWNER = address(this);

    function setUp() public { 
        c = new C(INITIAL_OWNER, IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); 
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint256).max);

        // Record the owner before the call
        address ownerBefore = c.owner();

        // Attempt depositAndStake - we expect it may revert (no booster set), but that's fine
        // The key invariant is that owner() should always return initial owner
        vm.prank(INITIAL_OWNER);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.depositAndStake.selector, amount));

        // Check owner after the call (whether it reverted or not, owner should be unchanged)
        address ownerAfter = c.owner();

        // The general rule: owner() always equals INITIAL_OWNER
        assertTrue(ownerBefore == INITIAL_OWNER && ownerAfter == INITIAL_OWNER);
    }
}

