// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property() public {
        // Set operator to a non-owner address
        address operator = address(0x42);
        c.setOperator(operator);

        // Renounce ownership - owner becomes address(0) in reference version
        c.renounceOwnership();

        // In the reference, owner() returns address(0), so operator is not owner
        // onlyOperatorOrOwner check: msg.sender == operator (true) so it should pass
        // In mutant, owner() returns address(0x1) but operator is still 0x42, so same check
        // Both should allow the call

        // call as operator
        vm.prank(operator);
        // This call should not revert in either version (since operator is set)
        c.depositAndStake(0);

        // The general rule: after renouncing ownership, depositAndStake can still be called by operator
        assertTrue(true);
    }
}

