pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(1)), ICVXBooster(address(2)), new address[](0)); }
    function testFuzz_property(uint32 pId, address token, address rewards) public {
        pId = uint32(bound(uint256(pId), 0, 10));
        vm.assume(token != address(0) && rewards != address(0));
        c.setCvxPoolInfo(pId, token, rewards);
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("isCvxShutdown()"));
        assertTrue(success);
        bool shutdown = abi.decode(data, (bool));
        (bool boosterSuccess, bytes memory boosterData) = address(c.booster()).staticcall(abi.encodeWithSignature("poolInfo(uint256)", pId));
        require(boosterSuccess, "booster call failed");
        (,,,bool boosterShutdown) = abi.decode(boosterData, (address,address,address,address,address,bool));
        assertTrue(shutdown == boosterShutdown);
    }
}

