pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // In the reference, owner() returns the deployer (address(this)).
        // The onlyOperator modifier checks msg.sender == operator, which is address(this) — passes.
        // In the mutation, owner() returns address(this) — same behavior here, so depositAndStake succeeds.
        // But to detect the bug, we need to call from a non-operator and non-owner.
        // However, the onlyOperator modifier will revert for any non-operator caller.
        // The difference manifests in the return value of owner() when called directly.
        // So we test: if we call owner() via c.owner(), the reference returns address(this) (the deployer),
        // while the mutation returns address(c).
        address ownerResult = c.owner();
        // The general rule: In the reference, owner() always returns the deployer (address(this)).
        // In the mutation, it returns address(c) instead.
        assertTrue(ownerResult == address(this), "owner() should be the deployer in the reference");
    }
}

