pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);

        // Simulate setup: set some pool info so isCvxShutdown() can be called without revert
        // We need to mock the booster.poolInfo call - since booster is address(0), we skip setup
        // Instead, we test the property that depends on owner() behavior

        // Record initial balance (zero for this contract as C)
        uint256 initialBalance = address(this).balance;

        // Try depositAndStake - may revert if operator check fails in buggy version
        (bool success, ) = address(c).call(abi.encodeWithSignature("depositAndStake(uint256)", amount));

        if (success) {
            // If deposit succeeded, the operator check passed
            // In reference: operator == address(this) so msg.sender (this contract) passes
            // In mutant: owner() returns address(this) which is not operator (address(this) of C), so it reverts
            // So success implies reference version was used, meaning owner() returned real owner
            assertTrue(c.isCvxShutdown() == false || c.clpToken() != IERC20(address(0)));
        } else {
            // If deposit reverted, it could be because operator check failed in buggy version
            // In buggy version: onlyOperator modifier checks msg.sender != operator, but operator is address(this) (C's address)
            // The caller here is address(this) (the test contract), which is not the operator (C's address)
            // So deposit reverts with NotOperator()
            assertTrue(msg.sender != c.operator());
        }
    }
}

