import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.assume(!c.isCvxShutdown());
        uint256 preBalance = c.stakedBalance();
        vm.assume(preBalance == 0);
        c.depositAndStake(amount);
        uint256 postBalance = c.stakedBalance();
        assertTrue(postBalance > 0);
    }
}

