pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is non-zero
        vm.assume(amount > 0);
        // Record the staked balance before
        uint256 before = c.stakedBalance();
        // Call depositAndStake (will revert if CVX pool is shutdown, but we ignore that)
        c.depositAndStake(amount);
        // After the call, staked balance should have increased by exactly amount
        uint256 after = c.stakedBalance();
        assertTrue(after == before + amount);
    }
}

