pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        // Ensure CVX pool is not shutdown: set pool info with shutdown = false
        // But we cannot directly set shutdown; we can assume it's not shutdown by the initial state
        // We'll pre-approve to set a known allowance and then check it decreases
        // First, record allowance before the call
        uint256 allowanceBefore = c.clpToken().allowance(address(c), c.booster());
        // Perform depositAndStake
        c.depositAndStake(amount);
        // After deposit, allowance should be less because safeIncreaseAllowance increases by amount, then deposit consumes it
        uint256 allowanceAfter = c.clpToken().allowance(address(c), c.booster());
        assertTrue(allowanceAfter < allowanceBefore + amount, "Allowance did not decrease as expected");
    }
}

