pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        // Deposit and stake
        c.depositAndStake(amount);
        // The rule: earned() must equal the underlying pool's earned() for this contract
        // Since the pool is address(0) (set up as 0 in constructor), it reverts, but the mutant always returns 0.
        // We use try/catch to handle the revert difference.
        bool poolReverted;
        uint256 poolEarned;
        try IBaseRewardPool(address(0)).earned(address(c)) {
            poolEarned = IBaseRewardPool(address(0)).earned(address(c));
        } catch {
            poolReverted = true;
        }
        bool contractReverted;
        uint256 contractEarned;
        try c.earned() {
            contractEarned = c.earned();
        } catch {
            contractReverted = true;
        }
        assertTrue(poolReverted == contractReverted);
        if (!poolReverted) {
            assertTrue(contractEarned == poolEarned);
        }
    }
}

