        // Record pool's earned before deposit (should be 0)
        uint256 poolEarnedBefore;
        try IBaseRewardPool(address(0)).earned(address(c)) {
            poolEarnedBefore = IBaseRewardPool(address(0)).earned(address(c));
        } catch { poolEarnedBefore = 0; }

        // Perform deposit
        c.depositAndStake(amount);

        // Record pool's earned after deposit
        uint256 poolEarnedAfter;
        try IBaseRewardPool(address(0)).earned(address(c)) {
            poolEarnedAfter = IBaseRewardPool(address(0)).earned(address(c));
        } catch { poolEarnedAfter = 0; }

        uint256 contractEarned = c.earned();

        // Rule: contract's earned() equals pool's earned(address(c)) after deposit
        assertTrue(contractEarned == poolEarnedAfter);
    }
}

